const request = require('supertest');
const app = require('../app');

describe('POST /users', () => {
  it('should create a user with valid data', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: 'Charlie' });

    expect(response.status).toBe(201);
    expect(response.body).toHaveProperty('id');
    expect(response.body.name).toBe('Charlie');
    expect(response.body.email).toBe('charlie@example.com');
  });

  it('should reject request without name', async () => {
    const response = await request(app)
      .post('/users')
      .send({});

    expect(response.status).toBe(400);
    expect(response.body.error).toBe('Bad Request');
    expect(response.body.message).toBe('Name is required');
  });

  it('should reject request with non-string name', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: 123 });

    expect(response.status).toBe(400);
    expect(response.body.error).toBe('Bad Request');
    expect(response.body.message).toBe('Name must be a string');
  });

  it('should reject request with empty name string', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: '' });

    // Note: This will pass since empty string is still a string type
    // Additional validation could be added if empty strings should be rejected
    expect(response.status).toBe(201);
    expect(response.body.name).toBe('');
  });
});

describe('GET /users', () => {
  it('should return list of users', async () => {
    const response = await request(app).get('/users');
    expect(response.status).toBe(200);
    expect(Array.isArray(response.body)).toBe(true);
    expect(response.body.length).toBe(2);
  });
});

describe('GET /health', () => {
  it('should return health status', async () => {
    const response = await request(app).get('/health');
    expect(response.status).toBe(200);
    expect(response.body.status).toBe('ok');
    expect(response.body).toHaveProperty('timestamp');
  });
});

